    diagram: ["promise   — pending → fulfilled (মান) বা rejected (error)", "await     — async function pause করে, page নয়; ক্রম নিশ্চিত", "all       — Promise.all: concurrent, INPUT ক্রমে ফল", "catch     — await ঘিরে try/catch rejection সামলায়"],
