  "l4-jsm-arrays": { recapEn: "map transforms, filter selects, reduce folds; sort is text by default and mutates — comparator and copy.", recapBn: "map transform করে, filter select করে, reduce ভাঁজ করে; sort default-এ text আর mutate করে — comparator আর copy।" },
  "l4-jsm-objects": { recapEn: "Destructure what you need, spread to copy-and-change, and remember JSON drops functions and undefined.", recapBn: "যা লাগে destructure করো, copy-আর-পরিবর্তনে spread, আর মনে রাখো JSON function আর undefined ফেলে দেয়।" },
  "l4-jsm-dom": { recapEn: "Build with createElement and textContent: data displayed, never parsed — the structural XSS fix.", recapBn: "createElement আর textContent দিয়ে বানাও: data প্রদর্শিত, কখনো parsed নয় — কাঠামোগত XSS সমাধান।" },
  "l4-jsm-events": { recapEn: "One parent listener, event.target, closest() to the row, dataset for data, preventDefault to own the action.", recapBn: "একটা parent listener, event.target, সারি পর্যন্ত closest(), data-র জন্য dataset, action-এর মালিক হতে preventDefault।" },
