  "l4-jsm-types": { en: ["If a comparison matters, it is === — no exceptions, no ==.", "Convert at the boundary (Number(...)) so the interior can stay strict."], bn: ["তুলনা গুরুত্বপূর্ণ হলে তা === — ব্যতিক্রম নেই, == নেই।", "Boundary-তে convert করো (Number(...)) যাতে ভেতরটা strict থাকতে পারে।"] },
  "l4-jsm-control": { en: ["for...of for values, for...in never for arrays.", "Guard clauses first; the happy path reads flat."], bn: ["Value-র জন্য for...of, array-র জন্য কখনো for...in নয়।", "আগে guard clause; happy path সমতল পড়ায়।"] },
  "l4-jsm-functions": { en: ["Braces on an arrow mean you owe a return statement.", "One factory call, one closure: interleave two counters to prove independence."], bn: ["Arrow-তে brace মানে তুমি একটা return statement-এর ঋণী।", "এক factory call, এক closure: স্বাধীনতা প্রমাণ করতে দুটো counter interleaved করো।"] },
  "l4-jsm-arrays": { en: ["Numbers never sort correctly without (a, b) => a - b.", "Spread-copy before sort/reverse/splice when the original must survive."], bn: ["(a, b) => a - b ছাড়া সংখ্যা কখনো ঠিকভাবে sort হয় না।", "আসলটা টিকতে হলে sort/reverse/splice-এর আগে spread-copy করো।"] },
  "l4-jsm-objects": { en: ["Later spread wins shared keys: defaults first, overrides after.", "Missing keys read as undefined — pair deep access with ?. and ??."], bn: ["পরের spread ভাগ করা key-তে জেতে: আগে default, পরে override।", "অনুপস্থিত key undefined পড়ায় — deep access ?. আর ??-এর সঙ্গে জুটি বাঁধো।"] },
  "l4-jsm-dom": { en: ["textContent for data, always; innerHTML with data is a finding.", "Select after the DOM exists — or defer the script."], bn: ["Data-র জন্য সবসময় textContent; data-সহ innerHTML একটা finding।", "DOM অস্তিত্বে আসার পরে select করো — বা script defer করো।"] },
  "l4-jsm-events": { en: ["Delegate dynamic lists: one parent listener covers future rows.", "Always guard the closest() result — padding clicks are not rows."], bn: ["Dynamic list delegate করো: একটা parent listener ভবিষ্যৎ সারি cover করে।", "closest() ফল সবসময় guard করো — padding click সারি নয়।"] },
  "l4-jsm-async": { en: ["Promise.all results follow input order, never finish order.", "An async function returns a promise — await it or handle it, never print it."], bn: ["Promise.all-এর ফল input ক্রম অনুসরণ করে, কখনো শেষ হওয়ার ক্রম নয়।", "async function promise ফেরত দেয় — await করো বা সামলাও, কখনো ছেপো না।"] },
  "l4-jsm-es6": { en: ["?. short-circuits the whole chain; ?? then supplies the stated default.", "Use Map when keys are not strings or order matters."], bn: ["?. পুরো chain short-circuit করে; ?? তারপর বলা default দেয়।", "Key string না হলে বা ক্রম গুরুত্বপূর্ণ হলে Map ব্যবহার করো।"] },
  "l4-jsm-security": { en: ["Escape & first, or your own escapes get double-encoded.", "javascript: is a protocol, not a link — allowlist href schemes."], bn: ["আগে & escape করো, নইলে নিজের escape-ই double-encode হবে।", "javascript: একটা protocol, link নয় — href scheme allowlist করো।"] },
